/**
 * Repository-normalized universal agent session event
 * This is the final normalized event structure after path normalization
 * It extends UniversalAgentSessionEvent with fully processed path information
 */

import { UniversalAgentSessionEvent } from './UniversalAgentSessionEvent';
import { NormalizedPathInfo, RepositoryInfo } from './PathNormalization';

/**
 * Repository context for the event
 * This is typically the repository of the working directory
 */
export interface EventRepositoryContext extends RepositoryInfo {
  // Repository root is always populated for event context
  root: string;
}

/**
 * Final event structure after repository path normalization
 * Replaces raw file paths with normalized path information
 */
export interface RepoNormalizedUniversalAgentSessionEvent
  extends Omit<UniversalAgentSessionEvent, 'rawFilePaths'> {
  // Repository context for the working directory (if in a repository)
  repository?: EventRepositoryContext;

  // Normalized file information (replaces rawFilePaths)
  // Files only include repository info if different from event.repository
  files?: NormalizedPathInfo[];

  // Working directory normalized to git root if in a repository
  normalizedWorkingDirectory?: string;
}